public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns an HTML code for embedding the message. Available only if messageProperties.can_get_embedding_code
    /// </summary>
    public Task<TdLib.TdApi.Objects.Text> GetMessageEmbeddingCodeAsync(long chatId = default, long messageId = default, bool forAlbum = default)
    {

           using var activity =  StartCallActivity("GetMessageEmbeddingCodeAsync", typeof(GetMessageEmbeddingCode).FullName ?? "GetMessageEmbeddingCodeAsync");

           try
           {
             return client.GetMessageEmbeddingCodeAsync(chatId, messageId, forAlbum);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
